package weibo

import (
	"compress/gzip"
	"io"
	"os"
	"path/filepath"
	"testing"

	"github.com/Brilliant666/DokiTool-Go/backend/internal/unified"
)

// This oracle is generated by the unmodified frozen PHP product functions;
// the CI job independently regenerates it using pinned PHP 8.3.6.
func TestPHPWeiboGuestProtocol(t *testing.T) {
	archive, err := os.Open(filepath.Join("testdata", "php-session-baseline.json.gz"))
	if err != nil {
		t.Fatal(err)
	}
	defer archive.Close()
	reader, err := gzip.NewReader(archive)
	if err != nil {
		t.Fatal(err)
	}
	defer reader.Close()
	content, err := io.ReadAll(io.LimitReader(reader, 1<<20))
	if err != nil {
		t.Fatal(err)
	}
	doc, err := unified.Decode(content)
	if err != nil {
		t.Fatal(err)
	}
	if doc["php_source_commit"] != "25beaee107f8c1a208ced9deb3c637068445e316" || !unified.Equal(doc["schema"], 1) {
		t.Fatal("unrecognized frozen PHP guest baseline")
	}
	cases := unified.Slice(doc["cases"])
	if len(cases) != 51 {
		t.Fatalf("unexpected guest baseline inventory: %d", len(cases))
	}
	for _, entry := range cases {
		entry := unified.Map(entry)
		t.Run(unified.Str(entry["id"]), func(t *testing.T) {
			args := unified.Map(entry["input"])
			var got any
			switch unified.Str(entry["operation"]) {
			case "transport":
				// A nil map stored in an interface is non-nil. Preserve the
				// JSON null result rather than introducing a typed-nil value.
				if failure := legacyTransportFailure(unified.Map(args["response"])); failure != nil {
					got = failure
				}
			case "visitor":
				got = legacyIsVisitor(unified.Map(args["response"]))
			case "jsonp":
				got = legacyJSONP(unified.Str(args["body"]), unified.Str(args["callback"]))
			default:
				t.Fatalf("unknown PHP oracle operation: %v", entry["operation"])
			}
			if !unified.Equal(got, entry["expected"]) {
				t.Fatalf("PHP mismatch: got %#v, want %#v", got, entry["expected"])
			}
		})
	}
}

func TestJSONPRejectsExecutableCode(t *testing.T) {
	for _, raw := range []string{
		"gen_callback({\"ok\":1});alert('bad')",
		"window.gen_callback && gen_callback({\"ok\":1});alert('bad')",
		"other({\"ok\":1});",
		"gen_callback([1,2]);",
	} {
		if got := legacyJSONP(raw, "gen_callback"); got != nil {
			t.Fatalf("should reject %q, got %#v", raw, got)
		}
	}
}
